// Wide contract: No preconditions, so noexcept is appropriate.
// It's guaranteed to work for any valid input.
int get_object_count() noexcept {
  // logic to count objects...
  return 42;
}

// Narrow contract: Precondition is that 'ptr' must not be null.
// Declaring this noexcept is risky.
void process_data_noexcept(int* ptr) noexcept {
  // Precondition: ptr != nullptr
  // If ptr is null, behavior is undefined. The implementer
  // CANNOT throw an exception to report this error.
  *ptr = 100;
}

// Narrow contract without noexcept is more flexible.
void process_data_flexible(int* ptr) {
  // Precondition: ptr != nullptr
  // An implementation *could* check and throw, e.g., in a debug build.
  if (!ptr) {
    // throw std::invalid_argument("Null pointer provided"); // Possible here
  }
  *ptr = 100;
}
